CREATE TABLE space_blueprint (
    template_key VARCHAR(32) NOT NULL,
    blueprint_version INTEGER NOT NULL CHECK (blueprint_version > 0),
    geometry_schema_version INTEGER NOT NULL CHECK (geometry_schema_version > 0),
    geometry JSONB NOT NULL CHECK (jsonb_typeof(geometry) = 'object'),
    CONSTRAINT valid_space_geometry_v1 CHECK (geometry_schema_version <> 1 OR (
        jsonb_typeof(geometry->'walls') = 'array'
        AND jsonb_typeof(geometry->'clearPaths') = 'array'
        AND jsonb_typeof(geometry->'entrance') = 'object'
        AND jsonb_typeof(geometry#>'{building,height}') = 'number'
        AND geometry#>'{building,height}' > '0'::jsonb
        AND jsonb_typeof(geometry#>'{building,minX}') = 'number'
        AND jsonb_typeof(geometry#>'{building,maxX}') = 'number'
        AND jsonb_typeof(geometry#>'{building,minZ}') = 'number'
        AND jsonb_typeof(geometry#>'{building,maxZ}') = 'number'
        AND geometry#>'{building,minX}' < geometry#>'{building,maxX}'
        AND geometry#>'{building,minZ}' < geometry#>'{building,maxZ}'
    ) IS TRUE),
    PRIMARY KEY (template_key, blueprint_version)
);

