CREATE TABLE space_blueprint_default (
    template_key VARCHAR(32) PRIMARY KEY,
    blueprint_version INTEGER NOT NULL,
    FOREIGN KEY (template_key, blueprint_version) REFERENCES space_blueprint
);

INSERT INTO space_blueprint_default (template_key, blueprint_version)
SELECT template_key, MAX(blueprint_version)
FROM space_blueprint GROUP BY template_key;

CREATE FUNCTION keep_published_space_blueprint() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
    RAISE EXCEPTION 'Published space blueprints are immutable; publish a new version';
END
$$;
CREATE TRIGGER immutable_space_blueprint BEFORE UPDATE OR DELETE ON space_blueprint
FOR EACH ROW EXECUTE FUNCTION keep_published_space_blueprint();

ALTER TABLE group_space
    ADD COLUMN blueprint_template_key VARCHAR(32),
    ADD COLUMN blueprint_version INTEGER,
    ADD CONSTRAINT fk_group_space_blueprint FOREIGN KEY (blueprint_template_key, blueprint_version)
        REFERENCES space_blueprint MATCH FULL;

-- Set only the reference. Unreadable or unmappable historical rows abort the migration atomically.
UPDATE group_space SET
    blueprint_template_key = room_json::jsonb->>'template',
    blueprint_version = (room_json::jsonb->>'version')::integer;

DO $$
BEGIN
    IF EXISTS (SELECT FROM group_space WHERE blueprint_template_key IS NULL OR blueprint_version IS NULL) THEN
        RAISE EXCEPTION 'Stored room has no historical blueprint key; inspect before migrating';
    END IF;
END
$$;

-- Blue/green legacy writers do not mention the new columns. Follow the submitted historical map
-- when its key changes; keep independent blueprint pins on ordinary edits.
CREATE FUNCTION match_legacy_space_blueprint() RETURNS trigger LANGUAGE plpgsql AS $$
DECLARE
    document jsonb;
    previous_document jsonb;
BEGIN
    document := NEW.room_json::jsonb;
    IF NEW.blueprint_template_key IS NULL AND NEW.blueprint_version IS NULL THEN
        NEW.blueprint_template_key := document->>'template';
        NEW.blueprint_version := (document->>'version')::integer;
    ELSIF TG_OP = 'UPDATE'
        AND (NEW.blueprint_template_key, NEW.blueprint_version)
            IS NOT DISTINCT FROM (OLD.blueprint_template_key, OLD.blueprint_version) THEN
        previous_document := OLD.room_json::jsonb;
        IF (previous_document->>'template', previous_document->>'version')
                IS DISTINCT FROM (document->>'template', document->>'version') THEN
            IF (OLD.blueprint_template_key, OLD.blueprint_version)
                    IS DISTINCT FROM (previous_document->>'template', (previous_document->>'version')::integer) THEN
                RAISE EXCEPTION 'Legacy writer cannot change a room pinned to a newer blueprint';
            END IF;
            NEW.blueprint_template_key := document->>'template';
            NEW.blueprint_version := (document->>'version')::integer;
        END IF;
    END IF;

    IF NEW.blueprint_template_key IS NULL OR NEW.blueprint_version IS NULL
            OR NEW.blueprint_template_key IS DISTINCT FROM (document->>'template') THEN
        RAISE EXCEPTION 'Stored room and blueprint template must match';
    END IF;
    RETURN NEW;
END
$$;
CREATE TRIGGER match_legacy_space_blueprint BEFORE INSERT OR UPDATE OF room_json, blueprint_template_key, blueprint_version
ON group_space FOR EACH ROW EXECUTE FUNCTION match_legacy_space_blueprint();

-- BEFORE triggers populate both columns for old writers before PostgreSQL checks constraints.
ALTER TABLE group_space
    ALTER COLUMN blueprint_template_key SET NOT NULL,
    ALTER COLUMN blueprint_version SET NOT NULL;
